const response = await fetch('http://localhost:8000/v1/tuning/start', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    base_model: 'llama-3-8b-instruct',
    dataset_path: '/workspace/dataset.jsonl',
    epochs: 3,
    learning_rate: 0.0002
  })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/tuning/start")
    .json(&serde_json::json!({
        "base_model": "llama-3-8b-instruct",
        "dataset_path": "/workspace/dataset.jsonl",
        "epochs": 3,
        "learning_rate": 0.0002
    }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

